@Composable fun PathPilotFullApp(viewModel:PathPilotViewModel){var screen by remember{mutableStateOf("home")};BackHandler(enabled=screen!="home"){screen="home"};Surface(Modifier.fillMaxSize(),color=Color(0xFFF7FAFF)){when(screen){"home"->Home({screen="learn"},{screen="projects"},{screen="git"},{screen="mentor"},{screen="college"});"learn"->Learn{screen="home"};"projects"->Projects{screen="home"};"git"->GitLab{screen="home"};"mentor"->Mentor{screen="home"};else->College{screen="home"}}}}

@Composable private fun Header(title:String="PathPilot",back:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(15.dp),verticalAlignment=Alignment.CenterVertically){if(back!=null)IconButton(back){Icon(Icons.Default.ArrowBack,"Back")};Surface(Modifier.size(43.dp),RoundedCornerShape(13.dp),Blue){Box(contentAlignment=Alignment.Center,modifier=Modifier.fillMaxSize()){Text("➤",color=Color.White,fontSize=23.sp,fontWeight=FontWeight.Black)}};Spacer(Modifier.width(9.dp));Column{Text(title,fontSize=21.sp,fontWeight=FontWeight.Black,color=Navy);Text("AI Engineering Academy",fontSize=9.sp,color=Gray)}}}

@Composable private fun Home(learn:()->Unit,projects:()->Unit,git:()->Unit,mentor:()->Unit,college:()->Unit){val ctx=androidx.compose.ui.platform.LocalContext.current;val pref=ctx.getSharedPreferences("pathpilot_progress",Context.MODE_PRIVATE);val done=skills.count{pref.getBoolean(it,false)};LazyColumn(contentPadding=PaddingValues(bottom=30.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header()};item{Text("Learn. Build. Debug. Ship.",Modifier.padding(horizontal=18.dp),fontSize=29.sp,fontWeight=FontWeight.Black,color=Navy)};item{Text("A practical mentor that makes you do real engineering work.",Modifier.padding(horizontal=18.dp),fontSize=12.sp,color=Gray)};item{Card(Modifier.padding(horizontal=18.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Soft),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(19.dp)){Text("TODAY",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Black);Text("LEARN → LAB → BUILD → DEBUG → REVIEW",fontSize=18.sp,fontWeight=FontWeight.Black,color=Navy);Text("Every skill becomes a real feature, bug, review or project milestone.",fontSize=11.sp,color=Gray,modifier=Modifier.padding(top=5.dp))}}};item{Card(Modifier.padding(horizontal=18.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Row{Text("Progress",fontWeight=FontWeight.Black,color=Navy,modifier=Modifier.weight(1f));Text("$done/${skills.size}",color=Blue,fontWeight=FontWeight.Bold)};LinearProgressIndicator({done.toFloat()/skills.size},Modifier.fillMaxWidth().padding(top=8.dp),color=Blue)}}};item{Row(Modifier.padding(horizontal=18.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Tile(Icons.Default.Code,"Learn",Soft,learn);Tile(Icons.Default.Folder,"Projects",Green,projects);Tile(Icons.Default.Terminal,"Git Lab",Purple,git)}};item{Row(Modifier.padding(horizontal=18.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Tile(Icons.Default.Psychology,"AI Mentor",Purple,mentor);Tile(Icons.Default.School,"College",Orange,college)}};item{Text("Professional workflow",Modifier.padding(horizontal=18.dp),fontSize=17.sp,fontWeight=FontWeight.Black,color=Navy)};item{Text("Requirements → tickets → branch → code → tests → commit → PR → CI → review → deploy → security → postmortem.",Modifier.padding(horizontal=18.dp),fontSize=12.sp,color=Gray)}}}
@Composable private fun RowScope.Tile(icon:androidx.compose.ui.graphics.vector.ImageVector,title:String,bg:Color,click:()->Unit){Card(Modifier.weight(1f).clickable(onClick=click),colors=CardDefaults.cardColors(bg),shape=RoundedCornerShape(15.dp)){Column(Modifier.padding(13.dp)){Icon(icon,null,tint=Blue);Spacer(Modifier.height(5.dp));Text(title,fontSize=11.sp,fontWeight=FontWeight.Bold,color=Navy)}}}

@Composable private fun Learn(back:()->Unit){val ctx=androidx.compose.ui.platform.LocalContext.current;val pref=ctx.getSharedPreferences("pathpilot_progress",Context.MODE_PRIVATE);var q by remember{mutableStateOf("")};val list=skills.filter{it.contains(q,true)};LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Header("Learn",back)};item{OutlinedTextField(q,{q=it},Modifier.padding(horizontal=16.dp).fillMaxWidth(),singleLine=true,label={Text("Search skills")})};items(list){s->Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(15.dp)){Row(Modifier.padding(15.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(pref.getBoolean(s,false))Icons.Default.CheckCircle else Icons.Default.Code,null,tint=Blue);Spacer(Modifier.width(9.dp));Column(Modifier.weight(1f)){Text(s,fontWeight=FontWeight.Black,color=Navy);Text("LEARN → LAB → BUILD → DEBUG → REVIEW",fontSize=10.sp,color=Gray)}};Text("Open",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Bold)}}}}

@Composable private fun Projects(back:()->Unit){LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){item{Header("Real Projects",back)};item{Text("Complete the project, not just the tutorial.",Modifier.padding(horizontal=18.dp),fontSize=23.sp,fontWeight=FontWeight.Black,color=Navy)};items(projects){p->Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(17.dp)){Text(p,fontSize=15.sp,fontWeight=FontWeight.Black,color=Navy);Text("Requirements → implementation → bug → tests → Git → PR → review → deployment → security → README",fontSize=11.sp,color=Gray,modifier=Modifier.padding(top=6.dp));Text("9 milestones",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=8.dp))}}}}}

@Composable private fun GitLab(back:()->Unit){var step by remember{mutableIntStateOf(0)};var input by remember{mutableStateOf("")};var msg by remember{mutableStateOf("")};val expected=git[step].lowercase();LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Header("Git + GitHub Practice",back)};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Navy),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(18.dp)){Text("TICKET → BRANCH → COMMIT → PR → CI → REVIEW → MERGE",fontSize=10.sp,color=Soft,fontWeight=FontWeight.Black);Text("Real developer workflow",fontSize=22.sp,color=Color.White,fontWeight=FontWeight.Black);LinearProgressIndicator({step.toFloat()/git.size},Modifier.fillMaxWidth().padding(top=10.dp),color=Blue)}}};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(17.dp)){Text("Step ${step+1}",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Black);Text(git[step],fontSize=19.sp,fontWeight=FontWeight.Black,color=Navy);OutlinedTextField(input,{input=it},Modifier.fillMaxWidth().padding(top=9.dp),singleLine=true,label={Text("Command / action")});Button({val ok=input.trim().lowercase()==expected||(expected=="git add ."&&input.trim().lowercase().startsWith("git add "));msg=if(ok)"✓ Correct. Next workflow step unlocked." else "Try again — follow the exact Git idea in the task.";if(ok&&step<git.lastIndex){step++;input=""}},Modifier.fillMaxWidth().padding(top=8.dp),shape=RoundedCornerShape(12.dp)){Text("Check")};if(msg.isNotBlank())Text(msg,fontSize=11.sp,color=if(msg.startsWith("✓"))Color(0xFF138A52) else Color(0xFFC2410C),modifier=Modifier.padding(top=7.dp))}}};items(git){Text("• $it",Modifier.padding(horizontal=20.dp),fontSize=11.sp,color=Gray)}}

@Composable private fun Mentor(back:()->Unit){var q by remember{mutableStateOf("")};var ans by remember{mutableStateOf("")};var loading by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();val ctx=androidx.compose.ui.platform.LocalContext.current;LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Header("AI Mentor",back)};item{Text("Ask a senior engineer. Learn the reasoning, then do the next action.",Modifier.padding(horizontal=18.dp),fontSize=22.sp,fontWeight=FontWeight.Black,color=Navy)};item{OutlinedTextField(q,{q=it},Modifier.padding(horizontal=16.dp).fillMaxWidth(),label={Text("What are you stuck on?")});Button({if(q.isNotBlank()){loading=true;scope.launch{ans=GeminiMentorService.askGeminiMentor(ctx,q,"PathPilot learner. Teach first, ask for evidence, give one concrete next action.");loading=false}}},Modifier.padding(horizontal=16.dp).fillMaxWidth(),enabled=q.isNotBlank()&&!loading,shape=RoundedCornerShape(12.dp)){Text(if(loading)"Thinking…" else "Ask Gemini")}};if(ans.isNotBlank())item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Text(ans,Modifier.padding(17.dp),fontSize=12.sp,color=Navy)}}}}

